package com.cpf.education.online.centercut.controller;
import com.cpf.education.online.centercut.dto.*;import com.cpf.education.online.centercut.service.SettlementCutService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.security.api.annotation.CpfPreAuthorize;import com.cpf.web.api.CpfRestController;import io.swagger.v3.oas.annotations.Operation;import org.springframework.web.bind.annotation.*;
/** Center-Cut 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfRestController @RequestMapping("/edu/online/settlement-cut") public class SettlementCutController {private final SettlementCutService service;public SettlementCutController(SettlementCutService s){service=s;}@PostMapping @CpfPreAuthorize("hasAuthority('CENTER_CUT_EXECUTE')") @Operation(operationId="EDU_CENTER_CUT_REQUEST",summary="Center-Cut 대응 온라인 거래") @CpfOnlineTransaction(operationId="EDU_CENTER_CUT_REQUEST",name="Center-Cut 대응 온라인 거래",description="Center-Cut 실행 접수와 상태 조회를 Public API로 수행한다.") public CenterCutView launch(@RequestBody SettlementCutCommand c)throws Exception{return service.launch(c);}}
